    internal val syllables: Array<String> by lazy { SYLLABLES_STRING.split(" ").toTypedArray() }

    private val extATable: ShortArray by lazy { decode(EXT_A_TABLE_STRING) }
    private val mainTable: ShortArray by lazy { decode(MAIN_TABLE_STRING) }

    private fun decode(s: String): ShortArray {
        val out = ShortArray(s.length / 2)
        for (i in out.indices) {
            val hi = ALPHABET.indexOf(s[i * 2])
            val lo = ALPHABET.indexOf(s[i * 2 + 1])
            out[i] = ((hi shl 6) or lo).toShort()
        }
        return out
    }

    /** 12-bit packed code for [c]; 0 means "not covered by the table". */
    internal fun codeOf(c: Char): Int {
        val cp = c.code
        return when (cp) {
            in MAIN_START..MAIN_END -> mainTable[cp - MAIN_START].toInt() and 0xFFFF
            in EXT_A_START..EXT_A_END -> extATable[cp - EXT_A_START].toInt() and 0xFFFF
            else -> 0
        }
    }
}
